// Minimal endless runner for <canvas id="game">
(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  const W = canvas.width = canvas.offsetWidth;
  const H = canvas.height = canvas.offsetHeight;

  // Game settings
  const GRAVITY = 0.6;
  const JUMP_SPEED = -12;
  let speed = 4; // initial ground speed (px/frame)
  let frame = 0;
  let running = true;
  let score = 0;

  // Background gradient
  const bgGrad = ctx.createLinearGradient(0, 0, 0, H);
  bgGrad.addColorStop(0, '#87ceeb'); // sky
  bgGrad.addColorStop(1, '#fff');

  // Simple particle for coin collection
  const particles = [];
  function spawnParticle(x, y, color) {
    particles.push({
      x, y,
      vx: (Math.random() - 0.5) * 2,
      vy: -Math.random() * 2,
      life: 30,
      color,
      draw() {
        ctx.fillStyle = this.color;
        ctx.globalAlpha = Math.max(this.life / 30, 0);
        ctx.beginPath();
        ctx.arc(this.x, this.y, 3, 0, Math.PI * 2);
        ctx.fill();
        ctx.globalAlpha = 1;
      }
    });
  }

  // Player object
  const player = {
    w: 30, h: 50,
    x: 50, y: H - 60,
    vy: 0,
    onGround: true,
    draw() {
      // rounded rectangle for nicer look
      ctx.fillStyle = '#0a0';
      ctx.beginPath();
      ctx.moveTo(this.x + 5, this.y);
      ctx.lineTo(this.x + this.w - 5, this.y);
      ctx.quadraticCurveTo(this.x + this.w, this.y, this.x + this.w, this.y + 5);
      ctx.lineTo(this.x + this.w, this.y + this.h - 5);
      ctx.quadraticCurveTo(this.x + this.w, this.y + this.h, this.x + this.w - 5, this.y + this.h);
      ctx.lineTo(this.x + 5, this.y + this.h);
      ctx.quadraticCurveTo(this.x, this.y + this.h, this.x, this.y + this.h - 5);
      ctx.lineTo(this.x, this.y + 5);
      ctx.quadraticCurveTo(this.x, this.y, this.x + 5, this.y);
      ctx.fill();
    },
    update() {
      this.vy += GRAVITY;
      this.y += this.vy;
      if (this.y + this.h >= H - 10) {
        this.y = H - 10 - this.h;
        this.vy = 0;
        this.onGround = true;
      } else {
        this.onGround = false;
      }
    },
    jump() {
      if (this.onGround) {
        this.vy = JUMP_SPEED;
        this.onGround = false;
      }
    }
  };

  // Simple obstacle generator
  const obstacles = [];
  function spawnObstacle() {
    const size = 30 + Math.random() * 20;
    const grad = ctx.createLinearGradient(0, H - 10 - size, 0, H - 10);
    grad.addColorStop(0, '#a00');
    grad.addColorStop(1, '#500');
    obstacles.push({
      x: W,
      y: H - 10 - size,
      w: size,
      h: size,
      draw() {
        ctx.fillStyle = grad;
        ctx.fillRect(this.x, this.y, this.w, this.h);
      }
    });
  }

  // Simple coin generator
  const coins = [];
  function spawnCoin() {
    const size = 15;
    const yPos = H - 10 - 80 - Math.random() * 120;
    const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, size / 2);
    grad.addColorStop(0, '#ff0');
    grad.addColorStop(1, '#c90');
    coins.push({
      x: W,
      y: yPos,
      r: size / 2,
      draw() {
        ctx.fillStyle = grad;
        ctx.beginPath();
        ctx.arc(this.x, this.y, this.r, 0, Math.PI * 2);
        ctx.fill();
      }
    });
  }

  // Input handling
  canvas.addEventListener('click', () => player.jump());
  canvas.addEventListener('touchstart', e => { e.preventDefault(); player.jump(); });

  function update() {
    // increase speed gradually
    if (frame % 600 === 0) speed += 0.5;

    // spawn obstacles/coins
    if (frame % Math.round(120 / speed) === 0) spawnObstacle();
    if (frame % Math.round(200 / speed) === 0) spawnCoin();

    // update player
    player.update();

    // update obstacles
    for (let i = obstacles.length - 1; i >= 0; i--) {
      const o = obstacles[i];
      o.x -= speed;
      if (o.x + o.w < 0) obstacles.splice(i, 1);
      // collision detection
      if (
        player.x < o.x + o.w &&
        player.x + player.w > o.x &&
        player.y < o.y + o.h &&
        player.y + player.h > o.y
      ) {
        running = false;
      }
    }

    // update coins and collect
    for (let i = coins.length - 1; i >= 0; i--) {
      const c = coins[i];
      c.x -= speed;
      // collect if player overlaps coin
      if (
        player.x < c.x + c.r &&
        player.x + player.w > c.x - c.r &&
        player.y < c.y + c.r &&
        player.y + player.h > c.y - c.r
      ) {
        score += 10;
        // spawn sparkle particles
        for (let p = 0; p < 8; p++) spawnParticle(c.x, c.y, '#ff0');
        coins.splice(i, 1);
        continue;
      }
      if (c.x + c.r < 0) coins.splice(i, 1);
    }

    // update particles
    for (let i = particles.length - 1; i >= 0; i--) {
      const p = particles[i];
      p.x += p.vx;
      p.y += p.vy;
      p.vy += 0.1; // gravity for particles
      p.life--;
      if (p.life <= 0) particles.splice(i, 1);
    }

    frame++;
  }

  function render() {
    // background
    ctx.fillStyle = bgGrad;
    ctx.fillRect(0, 0, W, H);
    // ground with gradient
    const groundGrad = ctx.createLinearGradient(0, H - 10, 0, H);
    groundGrad.addColorStop(0, '#444');
    groundGrad.addColorStop(1, '#222');
    ctx.fillStyle = groundGrad;
    ctx.fillRect(0, H - 10, W, 10);
    // entities
    player.draw();
    obstacles.forEach(o => o.draw());
    coins.forEach(c => c.draw());
    // particles
    particles.forEach(p => p.draw());
    // score
    ctx.fillStyle = '#000';
    ctx.font = '16px sans-serif';
    ctx.fillText('Score: ' + score, 10, 20);
  }

  function loop() {
    if (!running) {
      ctx.fillStyle = 'rgba(0,0,0,0.5)';
      ctx.fillRect(0,0,W,H);
      ctx.fillStyle = '#fff';
      ctx.font = '24px sans-serif';
      ctx.fillText('Game Over', W/2-60, H/2);
      ctx.fillText('Score: ' + score, W/2-60, H/2+30);
      return;
    }
    update();
    render();
    requestAnimationFrame(loop);
  }

  // start
  requestAnimationFrame(loop);
})();

